INSERT INTO UNIDADE_SAUDE (codigo_cnes, nome, razao_social, codigo_tipo_unidade, tipo_unidade, logradouro, numero,
  bairro, cep, codigo_municipio, uf, telefone, latitude, longitude, horario_funcionamento, atende_sus,
  status_acessibilidade, id_fonte, data_referencia_fonte)
SELECT x.cnes, x.nome, x.razao, x.cod_tipo, x.tipo, x.logradouro, x.numero, x.bairro, x.cep, x.municipio, x.uf,
