-- Regiao de cada unidade = bairro do cadastro CNES
UPDATE UNIDADE_SAUDE u SET id_regiao = (SELECT r.id_regiao FROM REGIAO r
  WHERE r.nome = u.bairro AND r.tipo_regiao = 'BAIRRO' AND r.codigo_municipio = u.codigo_municipio);

