  UNION ALL SELECT '9902325' cnes, 'SERVICO_APOIO' cod FROM dual
  UNION ALL SELECT '9961771' cnes, 'SERVICO_APOIO' cod FROM dual
  UNION ALL SELECT '9971513' cnes, 'SERVICO_APOIO' cod FROM dual
  UNION ALL SELECT '9986898' cnes, 'SERVICO_APOIO' cod FROM dual
  UNION ALL SELECT '9997091' cnes, 'SERVICO_APOIO' cod FROM dual
) x
JOIN UNIDADE_SAUDE u ON u.codigo_cnes = x.cnes
JOIN SERVICO_SAUDE s ON s.codigo = x.cod;
